export const envelope = [48, 32, 40];

export default function build(api) {
  const W = api.size[0];
  const H = api.size[1];
  const D = api.size[2];

  const PRISM = "minecraft:prismarine";
  const DARK = "minecraft:dark_prismarine";
  const LANTERN = "minecraft:sea_lantern";
  const BONE = "minecraft:bone_block";

  const ground = api.theme.ground;
  const pavement = ground.pavement;
  const kerb = ground.kerb;
  const revetment = ground.revetment;
  const scree = ground.scree;

  const directions = [
    [1, 0],
    [-1, 0],
    [0, 1],
    [0, -1]
  ];

  function mod(value, divisor) {
    return ((value % divisor) + divisor) % divisor;
  }

  function put(x, y, z, block) {
    x = Math.round(x);
    y = Math.round(y);
    z = Math.round(z);

    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) {
      return;
    }

    api.set(x, y, z, block);
  }

  function groundY(x, z) {
    let y = Math.floor(api.heightAt(x, z));
    if (y < 0) {
      y = 0;
    }
    return y;
  }

  function fillGround(x, z, extra, block) {
    x = Math.round(x);
    z = Math.round(z);

    if (x < 0 || x >= W || z < 0 || z >= D) {
      return;
    }

    const base = groundY(x, z);
    if (base >= H) {
      return;
    }

    let top = base + Math.max(0, Math.floor(extra));

    for (let i = 0; i < directions.length; i += 1) {
      const nx = x + directions[i][0];
      const nz = z + directions[i][1];

      if (nx >= 0 && nx < W && nz >= 0 && nz < D) {
        top = Math.max(top, groundY(nx, nz));
      }
    }

    top = Math.min(top, H - 1);

    for (let y = base; y <= top; y += 1) {
      put(x, y, z, block);
    }
  }

  function resolve(chooser, x, y, z) {
    return typeof chooser === "function" ? chooser(x, y, z) : chooser;
  }

  function ellipsoid(cx, cy, cz, rx, ry, rz, chooser, keep) {
    const x0 = Math.max(0, Math.floor(cx - rx));
    const x1 = Math.min(W - 1, Math.ceil(cx + rx));
    const y0 = Math.max(0, Math.floor(cy - ry));
    const y1 = Math.min(H - 1, Math.ceil(cy + ry));
    const z0 = Math.max(0, Math.floor(cz - rz));
    const z1 = Math.min(D - 1, Math.ceil(cz + rz));

    for (let x = x0; x <= x1; x += 1) {
      for (let y = y0; y <= y1; y += 1) {
        for (let z = z0; z <= z1; z += 1) {
          const dx = (x - cx) / rx;
          const dy = (y - cy) / ry;
          const dz = (z - cz) / rz;

          if (dx * dx + dy * dy + dz * dz > 1.0001) {
            continue;
          }

          if (keep && !keep(x, y, z)) {
            continue;
          }

          put(x, y, z, resolve(chooser, x, y, z));
        }
      }
    }
  }

  function ball(cx, cy, cz, radius, chooser) {
    const ix = Math.round(cx);
    const iy = Math.round(cy);
    const iz = Math.round(cz);
    const r = Math.ceil(radius);
    const limit = radius * radius + 0.35;

    for (let dx = -r; dx <= r; dx += 1) {
      for (let dy = -r; dy <= r; dy += 1) {
        for (let dz = -r; dz <= r; dz += 1) {
          const x = ix + dx;
          const y = iy + dy;
          const z = iz + dz;

          if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) {
            continue;
          }

          if (dx * dx + dy * dy + dz * dz <= limit) {
            put(x, y, z, resolve(chooser, x, y, z));
          }
        }
      }
    }
  }

  function tube(points, radii, chooser) {
    for (let s = 0; s < points.length - 1; s += 1) {
      const a = points[s];
      const b = points[s + 1];

      const span = Math.max(
        Math.abs(b[0] - a[0]),
        Math.abs(b[1] - a[1]),
        Math.abs(b[2] - a[2])
      );

      const steps = Math.max(1, Math.ceil(span * 2));

      for (let i = 0; i <= steps; i += 1) {
        const t = i / steps;
        const x = Math.round(a[0] + (b[0] - a[0]) * t);
        const y = Math.round(a[1] + (b[1] - a[1]) * t);
        const z = Math.round(a[2] + (b[2] - a[2]) * t);
        const radius = radii[s] + (radii[s + 1] - radii[s]) * t;

        ball(x, y, z, radius, chooser);
      }
    }
  }

  function skin(x, y, z, salt) {
    const value = mod(x * 17 + y * 13 + z * 7 + salt, 23);
    return value < 4 ? DARK : PRISM;
  }

  function tentacleSkin(x, y, z) {
    const value = mod(x * 11 + y * 5 + z * 17, 19);
    return value < 5 ? DARK : PRISM;
  }

  function headKeep(x, y, z) {
    const openingWidth = z < 5 ? 6 : 7;
    const cavity =
      z <= 13 &&
      Math.abs(x - 24) <= openingWidth &&
      y >= 10 &&
      y <= 18;

    return !cavity;
  }

  ellipsoid(24, 15, 25, 11, 9, 11, function (x, y, z) {
    return skin(x, y, z, 1);
  });

  ellipsoid(24, 11, 29, 8, 6, 9, function (x, y, z) {
    return skin(x, y, z, 5);
  });

  ellipsoid(24, 9, 25, 8, 3, 9, DARK);

  ellipsoid(16, 10, 33, 6, 3, 5, function (x, y, z) {
    return skin(x, y, z, 9);
  });

  ellipsoid(32, 10, 33, 6, 3, 5, function (x, y, z) {
    return skin(x, y, z, 12);
  });

  tube(
    [
      [21, 12, 31],
      [17, 10, 33]
    ],
    [2.5, 2.4],
    tentacleSkin
  );

  tube(
    [
      [27, 12, 31],
      [31, 10, 33]
    ],
    [2.5, 2.4],
    tentacleSkin
  );

  ellipsoid(
    24,
    17,
    12,
    11,
    10,
    10,
    function (x, y, z) {
      return skin(x, y, z, 19);
    },
    headKeep
  );

  ellipsoid(24, 22, 7, 9, 4, 7, function (x, y, z) {
    return skin(x, y, z, 23);
  });

  ellipsoid(24, 20, 2, 8, 3, 3, function (x, y, z) {
    return skin(x, y, z, 27);
  });

  ellipsoid(24, 7, 6, 9, 3, 7, function (x, y, z) {
    return skin(x, y, z, 31);
  });

  ellipsoid(24, 9, 12, 9, 3, 5, function (x, y, z) {
    return skin(x, y, z, 35);
  });

  ellipsoid(15, 14, 8, 4, 7, 6, function (x, y, z) {
    return skin(x, y, z, 39);
  });

  ellipsoid(33, 14, 8, 4, 7, 6, function (x, y, z) {
    return skin(x, y, z, 43);
  });

  for (let x = 18; x <= 30; x += 1) {
    for (let y = 12; y <= 17; y += 1) {
      put(x, y, 14, DARK);
    }
  }

  function makeEye(x) {
    for (let dx = -1; dx <= 1; dx += 1) {
      for (let dy = -1; dy <= 1; dy += 1) {
        put(x + dx, 21 + dy, 4, DARK);
      }
    }
    put(x, 22, 3, LANTERN);
  }

  makeEye(18);
  makeEye(30);

  const upperToothX = [19, 22, 26, 29];
  const upperToothZ = [2, 6, 10];

  for (let i = 0; i < upperToothX.length; i += 1) {
    for (let j = 0; j < upperToothZ.length; j += 1) {
      const lowest = 17 + mod(i + j + upperToothZ[j], 3);

      for (let y = lowest; y <= 21; y += 1) {
        put(upperToothX[i], y, upperToothZ[j], BONE);
      }
    }
  }

  const lowerToothX = [21, 24, 27];

  for (let i = 0; i < lowerToothX.length; i += 1) {
    for (let j = 0; j < upperToothZ.length; j += 1) {
      const highest = 12 - mod(i + j, 2);

      for (let y = 9; y <= highest; y += 1) {
        put(lowerToothX[i], y, upperToothZ[j], BONE);
      }
    }
  }

  tube(
    [
      [17, 20, 9],
      [15, 23, 8],
      [13, 25, 7]
    ],
    [1.4, 1.2, 1.0],
    BONE
  );

  tube(
    [
      [31, 20, 9],
      [33, 23, 8],
      [35, 25, 7]
    ],
    [1.4, 1.2, 1.0],
    BONE
  );

  tube(
    [
      [24, 22, 18],
      [24, 23, 23],
      [24, 23, 27],
      [24, 21, 30],
      [24, 18, 33],
      [24, 13, 37]
    ],
    [1.6, 1.5, 1.5, 1.4, 1.3, 1.1],
    BONE
  );

  const feet = [];

  function arm(points, foot, radii) {
    const gy = groundY(foot[0], foot[1]);
    const path = points.slice();
    path.push([foot[0], gy + 2, foot[1]]);

    const pathRadii = radii.slice();
    pathRadii.push(radii[radii.length - 1]);

    tube(path, pathRadii, tentacleSkin);
    feet.push([foot[0], foot[1]]);
  }

  arm(
    [
      [18, 9, 21],
      [15, 8, 17],
      [11, 6, 12],
      [8, 4, 7],
      [6, 3, 4]
    ],
    [4, 2],
    [3.3, 3.1, 2.9, 2.6, 2.5]
  );

  arm(
    [
      [30, 9, 21],
      [33, 8, 17],
      [37, 6, 12],
      [40, 4, 7],
      [42, 3, 4]
    ],
    [44, 2],
    [3.3, 3.1, 2.9, 2.6, 2.5]
  );

  arm(
    [
      [17, 10, 27],
      [12, 8, 24],
      [8, 6, 20],
      [6, 4, 16]
    ],
    [4, 13],
    [3.2, 3.0, 2.7, 2.4]
  );

  arm(
    [
      [31, 10, 27],
      [36, 8, 24],
      [40, 6, 20],
      [42, 4, 16]
    ],
    [44, 13],
    [3.2, 3.0, 2.7, 2.4]
  );

  arm(
    [
      [18, 10, 30],
      [15, 8, 31],
      [11, 6, 33],
      [8, 4, 35]
    ],
    [7, 36],
    [3.1, 2.9, 2.6, 2.3]
  );

  arm(
    [
      [30, 10, 30],
      [33, 8, 31],
      [37, 6, 33],
      [40, 4, 35]
    ],
    [41, 36],
    [3.1, 2.9, 2.6, 2.3]
  );

  arm(
    [
      [21, 8, 20],
      [20, 7, 15],
      [19, 5, 10],
      [18, 3, 5]
    ],
    [18, 2],
    [3.0, 2.8, 2.5, 2.3]
  );

  arm(
    [
      [27, 8, 20],
      [28, 7, 15],
      [29, 5, 10],
      [30, 3, 5]
    ],
    [30, 2],
    [3.0, 2.8, 2.5, 2.3]
  );

  for (let x = 6; x <= 42; x += 1) {
    const material = x % 6 <= 1 ? kerb : pavement;
    fillGround(x, 0, 1, material);
  }

  function debrisPatch(x0, x1, z0, z1, baseBlock, phase) {
    for (let x = x0; x <= x1; x += 1) {
      for (let z = z0; z <= z1; z += 1) {
        const value = mod(x * 7 + z * 11 + phase, 9);
        const keep = z === z0 || value !== 0;

        if (!keep) {
          continue;
        }

        const height = z === z0 ? 1 : (value % 5 === 0 ? 2 : 0);
        const material = value === 1 ? revetment : baseBlock;
        fillGround(x, z, height, material);
      }
    }
  }

  debrisPatch(8, 14, 1, 4, pavement, 1);
  debrisPatch(16, 21, 1, 3, revetment, 2);
  debrisPatch(29, 34, 1, 4, pavement, 3);
  debrisPatch(36, 42, 1, 3, scree, 4);

  const craters = [
    [24, 6],
    [22, 11],
    [26, 17],
    [24, 22]
  ];

  function craterAt(x, z) {
    for (let i = 0; i < craters.length; i += 1) {
      const dx = x - craters[i][0];
      const dz = z - craters[i][1];

      if (dx * dx + dz * dz <= 1) {
        return true;
      }
    }

    return false;
  }

  for (let z = 0; z <= 25; z += 1) {
    const center = 24 + Math.floor(2 * Math.sin(z * 0.7));
    const width = z < 3 ? 3 : 4;

    for (let x = center - width; x <= center + width; x += 1) {
      const crater = craterAt(x, z);
      let rise = z >= 4 && z <= 12 ? 4 : 1;

      if (mod(x * 3 + z * 5, 11) === 0) {
        rise += 1;
      }

      if (crater) {
        rise = 0;
      }

      const material = crater
        ? DARK
        : (mod(x * 13 + z * 17, 7) < 2 ? PRISM : DARK);

      fillGround(x, z, rise, material);
    }
  }

  for (let i = 0; i < craters.length; i += 1) {
    const cx = craters[i][0];
    const cz = craters[i][1];

    for (let dx = -3; dx <= 3; dx += 1) {
      for (let dz = -3; dz <= 3; dz += 1) {
        const distance = dx * dx + dz * dz;

        if (distance < 2 || distance > 10) {
          continue;
        }

        const value = mod((cx + dx) * 5 + (cz + dz) * 13 + i, 6);
        const material = value === 0 ? scree : DARK;
        fillGround(cx + dx, cz + dz, 2 + (value === 1 ? 1 : 0), material);
      }
    }
  }

  function footPad(cx, cz, index) {
    for (let dx = -3; dx <= 3; dx += 1) {
      for (let dz = -3; dz <= 3; dz += 1) {
        if (dx * dx + dz * dz > 9) {
          continue;
        }

        const value = mod(cx * 7 + cz * 11 + dx * 3 + dz * 5 + index, 5);
        const material = value === 0 ? DARK : PRISM;
        fillGround(cx + dx, cz + dz, value === 1 ? 2 : 1, material);
      }
    }
  }

  for (let i = 0; i < feet.length; i += 1) {
    footPad(feet[i][0], feet[i][1], i);
  }

  function crushedSite(cx, cz, phase) {
    for (let dx = -3; dx <= 3; dx += 1) {
      for (let dz = -3; dz <= 3; dz += 1) {
        const distance = dx * dx + dz * dz;

        if (distance > 12) {
          continue;
        }

        const value = mod((cx + dx) * 5 + (cz + dz) * 3 + phase * 11, 9);

        if (distance > 1 && value === 0) {
          continue;
        }

        const height = distance <= 2 ? 2 : (value % 3 === 0 ? 2 : 1);
        const material =
          value % 4 === 0
            ? scree
            : (value % 3 === 0 ? revetment : pavement);

        fillGround(cx + dx, cz + dz, height, material);
      }
    }

    const pillarX = cx + (phase % 2 === 0 ? 2 : -2);
    const pillarZ = cz + (phase % 2 === 0 ? 1 : 0);
    fillGround(pillarX, pillarZ, 3, revetment);
  }

  for (let i = 0; i < 4; i += 1) {
    crushedSite(feet[i][0], feet[i][1], i);
  }

  return {
    name: "Harbor Maw Leviathan",
    seatY: 0,
    anchors: {
      quay: [24, 1, 0],
      maw: [24, 14, 1],
      wake: [24, 2, 10],
      spine: [24, 24, 25]
    }
  };
}

