export const envelope = [15, 18, 15];

export default function build(api) {
  const W = api.size[0];
  const H = api.size[1];
  const D = api.size[2];
  const idx = api.instance.index;
  const count = api.instance.count;

  const dice = [];
  for (let i = 0; i < 12; i += 1) {
    dice.push(api.random());
  }

  const prismarine = "minecraft:prismarine";
  const darkPrismarine = "minecraft:dark_prismarine";
  const eyeBlock = "minecraft:glowstone";

  const ground = api.theme.ground;
  const wood = api.theme.wood;
  const stone = api.theme.stone;

  const pavement = ground.pavement;
  const kerb = ground.kerb;
  const scree = ground.scree;
  const foam = ground.weep;
  const plinth = ground.plinth;
  const rail = ground.rail;

  const woodLog = wood.log;
  const woodPlanks = wood.planks;
  const stonePrimary = stone.primary;
  const stoneAccent = stone.accent;

  const heading = (idx + count + Math.floor(dice[0] * 4)) % 4;
  const alongZ = heading === 0 || heading === 1;
  const sign = heading === 0 || heading === 2 ? 1 : -1;

  const alongLimit = alongZ ? D - 1 : W - 1;
  const crossLimit = alongZ ? W - 1 : D - 1;
  const start = sign > 0 ? 2 : 12;

  const lateralBase =
    6 + ((idx * 2 + count + Math.floor(dice[1] * 3)) % 3);
  const swayAmp = 1 + ((idx + Math.floor(dice[2] * 5)) % 2);
  const phase = Math.floor(dice[2] * 12) + idx * 2 + count;
  const length = 10 + ((idx + Math.floor(dice[3] * 4)) % 2);
  const bodyR = 2 + ((idx + Math.floor(dice[4] * 5)) % 2);
  const bodyRy = 2 + ((idx + Math.floor(dice[5] * 7)) % 2);
  const footR = 3;

  function clamp(value, low, high) {
    return Math.max(low, Math.min(high, value));
  }

  function toXYZ(a, l, y) {
    return alongZ ? [l, y, a] : [a, y, l];
  }

  function putAt(a, l, y, block) {
    const p = toXYZ(a, l, y);
    const x = Math.round(p[0]);
    const yy = Math.round(p[1]);
    const z = Math.round(p[2]);

    if (x >= 0 && x < W && yy >= 0 && yy < H && z >= 0 && z < D) {
      api.set(x, yy, z, block);
    }
  }

  function groundAt(a, l) {
    const p = toXYZ(a, l, 0);

    if (p[0] < 0 || p[0] >= W || p[2] < 0 || p[2] >= D) {
      return 0;
    }

    const h = Math.floor(api.heightAt(p[0], p[2]));
    return clamp(h, 0, H - 1);
  }

  let terrainPeak = 0;

  for (let a = 4; a <= 10; a += 3) {
    for (let l = 4; l <= 10; l += 3) {
      const p = toXYZ(a, l, 0);
      const h = Math.floor(api.heightAt(p[0], p[2]));

      if (h > terrainPeak) {
        terrainPeak = h;
      }
    }
  }

  const lift = clamp(terrainPeak, 0, 3);

  function center(t) {
    const progress = clamp(t / (length - 1), 0, 1);
    const wiggle =
      swayAmp * Math.sin((t + phase) * 0.78) +
      0.35 * Math.sin((t * 2 + phase) * 0.41);
    const lateral = lateralBase + Math.round(wiggle);
    const bob = Math.round(0.8 * Math.sin((t + phase) * 0.95));
    const y = 4 + lift + Math.floor(progress * 2) + bob;

    return {
      a: start + sign * t,
      l: lateral,
      y: y
    };
  }

  function blob(a, l, y, ra, rl, ry, block) {
    for (let da = -ra; da <= ra; da += 1) {
      for (let dl = -rl; dl <= rl; dl += 1) {
        for (let dy = -ry; dy <= ry; dy += 1) {
          const shape =
            (da * da) / (ra * ra) +
            (dl * dl) / (rl * rl) +
            (dy * dy) / (ry * ry);

          if (shape <= 1.001) {
            putAt(a + da, l + dl, y + dy, block);
          }
        }
      }
    }
  }

  const trailWidth = footR + 1;

  for (let t = -2; t < length; t += 1) {
    const c = center(t);

    for (let dl = -trailWidth; dl <= trailWidth; dl += 1) {
      const g = groundAt(c.a, c.l + dl);
      const pattern = Math.abs(t * 13 + dl * 7 + idx * 5 + phase) % 13;
      let block;

      if (Math.abs(dl) === trailWidth) {
        block = kerb;
      } else if (pattern <= 1) {
        block = foam;
      } else if (pattern <= 4) {
        block = scree;
      } else if (pattern === 6 && Math.abs(dl) >= bodyR) {
        block = darkPrismarine;
      } else if (pattern === 8 && t >= 0) {
        block = stonePrimary;
      } else {
        block = pavement;
      }

      putAt(c.a, c.l + dl, g, block);
    }
  }

  for (let t = 0; t < length; t += 2) {
    const c = center(t);
    const side = (t + idx) % 2 === 0 ? -1 : 1;
    const l = c.l + side * (trailWidth - 1);
    const g = groundAt(c.a, l);

    putAt(c.a, l, g, (t + idx) % 4 === 0 ? foam : scree);
  }

  for (let t = 0; t < length; t += 1) {
    const c = center(t);

    for (let dl = -footR; dl <= footR; dl += 1) {
      const g = groundAt(c.a, c.l + dl);
      const edge = Math.abs(dl) >= bodyR;
      const top = c.y - (edge ? 1 : Math.max(0, bodyRy - 2));

      for (let y = g; y <= top; y += 1) {
        const pattern = Math.abs(t * 17 + dl * 3 + y + idx) % 6;
        const block =
          y < c.y - 1 || pattern === 0
            ? darkPrismarine
            : prismarine;

        putAt(c.a, c.l + dl, y, block);
      }
    }
  }

  const damageLevel = Math.floor(dice[7] * 4);

  for (let t = 0; t < length; t += 1) {
    const c = center(t);

    for (let dl = -bodyR; dl <= bodyR; dl += 1) {
      for (let dy = -bodyRy; dy <= bodyRy; dy += 1) {
        const shape =
          (dl * dl) / (bodyR * bodyR) +
          (dy * dy) / (bodyRy * bodyRy);

        if (shape <= 1.001) {
          const surface =
            Math.abs(dl) >= bodyR - 1 ||
            Math.abs(dy) >= bodyRy - 1;
          const holePattern =
            Math.abs(t * 19 + dl * 7 + dy * 5 + idx * 3 + phase) % 19;
          const hole =
            damageLevel > 0 &&
            surface &&
            t > 0 &&
            t < length - 1 &&
            holePattern < damageLevel;

          if (!hole) {
            const texture =
              Math.abs(t * 19 + dl * 7 + dy * 5 + idx + phase) % 9;
            const block =
              dy < 0 || texture === 0 || (texture === 1 && dl < 0)
                ? darkPrismarine
                : prismarine;

            putAt(c.a, c.l + dl, c.y + dy, block);
          }
        }
      }
    }
  }

  const ribCount =
    2 + ((idx + Math.floor(dice[8] * 5) + count) % 2);

  for (let b = 0; b < ribCount; b += 1) {
    let ribT;

    if (b === 0) {
      ribT = 2;
    } else if (b === 1) {
      ribT = Math.floor(length / 2);
    } else {
      ribT = length - 3;
    }

    const ribShift =
      (idx + Math.floor(dice[9] * 3) + b) % 3 - 1;
    ribT = clamp(ribT + ribShift, 2, length - 3);

    const c = center(ribT);
    const ribY = c.y + 1 + (b % 2);
    const block =
      (b + idx) % 2 === 0
        ? prismarine
        : darkPrismarine;

    blob(c.a, c.l, ribY, 2, bodyR + 1, bodyRy + 1, block);
  }

  const first = center(0);
  const tailA = first.a - sign;

  blob(
    tailA,
    first.l,
    Math.max(1, first.y - 1),
    1,
    1,
    1,
    darkPrismarine
  );

  for (let dl = -1; dl <= 1; dl += 1) {
    const g = groundAt(tailA, first.l + dl);

    for (let y = g; y <= first.y - 2; y += 1) {
      putAt(tailA, first.l + dl, y, darkPrismarine);
    }
  }

  const farA = first.a - sign * 2;
  const farGround = groundAt(farA, first.l);

  for (let y = farGround; y <= first.y - 2; y += 1) {
    putAt(farA, first.l, y, darkPrismarine);
  }

  const last = center(length - 1);
  const headA = last.a;
  const headL = last.l;
  const headR =
    2 + ((idx + Math.floor(dice[6] * 7)) % 2);
  const headRy = 3;
  const headDepth = 2;
  const headRise =
    (idx + Math.floor(dice[3] * 5) + count) % 3;
  const headY = 9 + lift + headRise;

  blob(
    headA - sign,
    headL,
    headY - 2,
    2,
    Math.min(bodyR + 1, headR + 1),
    2,
    (idx + count) % 2 === 0
      ? darkPrismarine
      : prismarine
  );

  const headDamage = Math.floor(dice[7] * 3);

  for (let da = -headDepth; da <= headDepth; da += 1) {
    for (let dl = -headR; dl <= headR; dl += 1) {
      for (let dy = -headRy; dy <= headRy; dy += 1) {
        const shape =
          (da * da) / (headDepth * headDepth) +
          (dl * dl) / (headR * headR) +
          (dy * dy) / (headRy * headRy);

        if (shape <= 1.001) {
          const surface =
            Math.abs(da) === headDepth ||
            Math.abs(dl) === headR ||
            Math.abs(dy) === headRy;
          const damagePattern =
            Math.abs(da * 5 + dl * 7 + dy * 3 + idx + phase) % 17;
          const front = da * sign > 0;
          const protectEye =
            front && Math.abs(dl) <= 1 && dy >= 0;
          const hole =
            headDamage > 0 &&
            surface &&
            damagePattern < headDamage;

          if (!hole || protectEye) {
            const texture =
              Math.abs(da * 7 + dl * 3 + dy * 5 + idx * 2 + phase) % 8;
            const block =
              dy < 0 || texture === 0 || (front && dy === 0)
                ? darkPrismarine
                : prismarine;

            putAt(
              headA + sign * da,
              headL + dl,
              headY + dy,
              block
            );
          }
        }
      }
    }
  }

  const finCount =
    1 + ((idx + Math.floor(dice[10] * 5)) % 3);

  for (let f = 0; f < finCount; f += 1) {
    const finT =
      1 +
      ((f * 3 + idx + Math.floor(dice[11] * 7)) %
        (length - 2));
    const finHeight =
      2 + ((f + idx + Math.floor(dice[9] * 5)) % 3);

    for (let dt = -1; dt <= 1; dt += 1) {
      const tt = clamp(finT + dt, 0, length - 1);
      const c = center(tt);
      const localHeight = finHeight - Math.abs(dt);

      for (let fy = 0; fy <= localHeight; fy += 1) {
        const block =
          (fy + f + idx) % 2 === 0
            ? darkPrismarine
            : prismarine;

        putAt(
          c.a,
          c.l,
          c.y + bodyRy - 1 + fy,
          block
        );

        if (dt === 0 && fy === 0) {
          putAt(
            c.a,
            c.l - 1,
            c.y + bodyRy - 1,
            block
          );
          putAt(
            c.a,
            c.l + 1,
            c.y + bodyRy - 1,
            block
          );
        }
      }
    }
  }

  const sideFinMode =
    (idx + count + Math.floor(dice[6] * 5)) % 3;
  const sideFinCount =
    1 + ((idx + Math.floor(dice[9] * 4)) % 2);

  for (let f = 0; f < sideFinCount; f += 1) {
    const finT =
      2 +
      ((f * 4 + idx + Math.floor(dice[8] * 5)) %
        (length - 4));
    const c = center(finT);

    for (let s = -1; s <= 1; s += 2) {
      const chosenSide =
        (f + idx) % 2 === 0 ? -1 : 1;

      if (sideFinMode === 0 && s !== chosenSide) {
        continue;
      }

      for (let d = bodyR - 1; d <= bodyR + 1; d += 1) {
        const block =
          (d + s + f + idx) % 2 === 0
            ? prismarine
            : darkPrismarine;

        putAt(c.a, c.l + s * d, c.y, block);

        if (d === bodyR - 1) {
          putAt(c.a, c.l + s * d, c.y + 1, block);
        }
      }
    }
  }

  const faceA = headA + sign * headDepth;

  for (let ml = -1; ml <= 1; ml += 1) {
    putAt(faceA, headL + ml, headY - 1, darkPrismarine);

    if (Math.abs(ml) === 1) {
      putAt(faceA, headL + ml, headY - 2, darkPrismarine);
    }
  }

  putAt(faceA - sign, headL, headY - 2, darkPrismarine);

  for (let eyeSide = -1; eyeSide <= 1; eyeSide += 2) {
    putAt(
      faceA,
      headL + eyeSide,
      headY,
      darkPrismarine
    );
    putAt(
      faceA,
      headL + eyeSide,
      headY + 1,
      eyeBlock
    );
  }

  const tentacleCount =
    3 + ((idx + Math.floor(dice[10] * 5)) % 2);
  const tentacles = [];

  for (let q = 0; q < tentacleCount; q += 1) {
    let startA;
    let startL;
    let targetA;
    let targetL;

    if (q === 0 || q === 1) {
      const side = q === 0 ? -1 : 1;

      startA = headA - sign;
      startL = headL + side * (headR - 1);
      targetA = headA - sign;
      targetL = headL + side * (headR + 1);
    } else if (q === 2) {
      const lateralJitter =
        (idx + Math.floor(dice[1] * 5)) % 3 - 1;

      startA = headA + sign;
      startL = headL + lateralJitter;
      targetA = headA + sign * 2;
      targetL =
        headL +
        lateralJitter +
        (idx % 2 === 0 ? 1 : -1);
    } else {
      const side = (idx + q) % 2 === 0 ? -1 : 1;

      startA = headA - sign;
      startL = headL + side * (headR - 1);
      targetA = headA - sign * 2;
      targetL = headL + side * (headR + 2);
    }

    startA = clamp(startA, 0, alongLimit);
    startL = clamp(startL, 1, crossLimit - 1);
    targetA = clamp(targetA, 0, alongLimit);
    targetL = clamp(targetL, 1, crossLimit - 1);

    const startY = Math.max(2, headY - 1);
    const endGround = groundAt(targetA, targetL);
    const endY = Math.min(startY, endGround);
    const steps = Math.max(
      6,
      startY - endY + 2 + ((q + idx) % 2)
    );

    tentacles.push({
      sa: startA,
      sl: startL,
      sy: startY,
      ea: targetA,
      el: targetL,
      ey: endY,
      steps: steps
    });
  }

  for (let q = 0; q < tentacles.length; q += 1) {
    const t = tentacles[q];

    for (let da = -1; da <= 1; da += 1) {
      for (let dl = -1; dl <= 1; dl += 1) {
        if (Math.abs(da) + Math.abs(dl) > 1) {
          continue;
        }

        const gy = groundAt(t.ea + da, t.el + dl);
        const patchY = Math.min(t.sy, gy);
        const pattern =
          Math.abs(q * 7 + idx * 5 + da * 3 + dl * 11 + phase) % 5;
        const block = pattern < 2 ? foam : scree;

        putAt(t.ea + da, t.el + dl, patchY, block);
      }
    }

    if ((q + idx + count) % 2 === 0) {
      putAt(t.ea, t.el, t.ey, darkPrismarine);
    }
  }

  function drawTentacle(t, q) {
    let a = t.sa;
    let l = t.sl;
    let y = t.sy;

    const initialRadius =
      (q + idx) % 3 === 0 ? 2 : 1;

    blob(
      a,
      l,
      y,
      initialRadius,
      initialRadius,
      initialRadius,
      (q + idx) % 2 === 0
        ? darkPrismarine
        : prismarine
    );

    for (let k = 1; k <= t.steps; k += 1) {
      const na = Math.round(
        t.sa + ((t.ea - t.sa) * k) / t.steps
      );
      const nl = Math.round(
        t.sl + ((t.el - t.sl) * k) / t.steps
      );
      const ny = Math.round(
        t.sy + ((t.ey - t.sy) * k) / t.steps
      );

      const radius =
        k <= 2 && (q + idx) % 2 === 0 ? 2 : 1;
      const block =
        (q + k + idx) % 4 === 0
          ? darkPrismarine
          : prismarine;

      while (y !== ny) {
        y += y < ny ? 1 : -1;
        blob(a, l, y, radius, radius, radius, block);
      }

      while (a !== na) {
        a += a < na ? 1 : -1;
        blob(a, l, y, radius, radius, radius, block);
      }

      while (l !== nl) {
        l += l < nl ? 1 : -1;
        blob(a, l, y, radius, radius, radius, block);
      }

      blob(a, l, y, radius, radius, radius, block);
    }
  }

  for (let q = 0; q < tentacles.length; q += 1) {
    drawTentacle(tentacles[q], q);
  }

  const furnitureCount =
    1 + ((idx + Math.floor(dice[11] * 6)) % 3);

  for (let q = 0; q < furnitureCount; q += 1) {
    const span = Math.max(1, length - 2);
    const t =
      1 +
      ((q * 3 + idx + Math.floor(dice[9] * 9)) % span);
    const c = center(t);
    const kind = q % 3;

    let side =
      (q + idx + count) % 2 === 0 ? -1 : 1;
    let available =
      side < 0
        ? c.l - bodyR
        : crossLimit - c.l - bodyR;

    if (available < 2) {
      side = -side;
      available =
        side < 0
          ? c.l - bodyR
          : crossLimit - c.l - bodyR;
    }

    const desired =
      2 + ((q + idx + Math.floor(dice[9] * 6)) % 3);
    const beamLength = Math.max(
      1,
      Math.min(desired, available)
    );

    let previousGround = -1;

    for (let j = 0; j <= beamLength; j += 1) {
      const l = c.l + side * (bodyR + j);
      const g = groundAt(c.a, l);

      if (previousGround >= 0) {
        const low = Math.min(previousGround, g);
        const high = Math.max(previousGround, g);

        for (let yy = low; yy <= high; yy += 1) {
          putAt(
            c.a,
            l,
            yy,
            kind === 2 ? plinth : woodLog
          );
        }
      }

      if (kind === 2) {
        putAt(c.a, l, g, plinth);

        if (g + 1 < H) {
          putAt(c.a, l, g + 1, rail);
        }
      } else {
        putAt(c.a, l, g, woodLog);
      }

      previousGround = g;
    }

    const endL = c.l + side * (bodyR + beamLength);
    const endG = groundAt(c.a, endL);

    if (kind === 0) {
      putAt(c.a, endL, endG, woodPlanks);

      const panelA = clamp(
        c.a + (q % 2 === 0 ? sign : -sign),
        0,
        alongLimit
      );

      putAt(panelA, endL, endG, woodPlanks);
    } else if (kind === 1) {
      putAt(c.a, endL, endG, stoneAccent);

      if (endG + 1 < H) {
        putAt(c.a, endL, endG + 1, woodPlanks);
      }
    } else {
      putAt(c.a, endL, endG, woodPlanks);
    }
  }

  const code = idx + 1;

  for (let bit = 0; bit < 5; bit += 1) {
    const c = center(bit + 1);

    putAt(
      c.a,
      c.l,
      c.y + bodyRy - 1,
      prismarine
    );
    putAt(
      c.a,
      c.l,
      c.y + bodyRy,
      (code & (1 << bit)) !== 0
        ? darkPrismarine
        : prismarine
    );
  }

  function anchorAt(a, l, y) {
    const p = toXYZ(a, l, y);
    return [p[0], p[1], p[2]];
  }

  const frontA = clamp(
    headA + sign * 2,
    0,
    alongLimit
  );

  return {
    name: "Sea Monster Breacher",
    seatY: 0,
    anchors: {
      breach: anchorAt(
        farA,
        first.l,
        groundAt(farA, first.l)
      ),
      advance: anchorAt(
        frontA,
        headL,
        groundAt(frontA, headL)
      ),
      head: anchorAt(headA, headL, headY),
      eye: anchorAt(faceA, headL, headY + 1)
    }
  };
}
